package firewall

import (
	"errors"
	"fmt"
	"strings"
	"time"
)

// Action is what a rule does to matching traffic.
type Action string

// Block drops matching outgoing traffic. It is the only action: everything
// that no rule blocks is allowed.
const Block Action = "block"

// Rule blocks outgoing traffic of one program, to one destination, or of
// one program to one destination.
type Rule struct {
	// ID identifies the rule. It is generated by Add and never changes.
	ID string `json:"id"`
	// App is the display name of the program; "" with an empty Exe means
	// any program.
	App string `json:"app,omitempty"`
	// Exe is the program's full executable path. Windows and Linux need it
	// to block a program.
	Exe string `json:"exe,omitempty"`
	// Dest is "" for every destination, or an IP address, a CIDR prefix or
	// a host name. Host names are resolved to addresses whenever the rules
	// are applied.
	Dest string `json:"dest,omitempty"`
	// Note is the user's free-form comment.
	Note string `json:"note,omitempty"`
	// Created is when the rule was added.
	Created time.Time `json:"created"`
	// Enabled is false for a rule the user has paused.
	Enabled bool `json:"enabled"`
}

// Action returns what the rule does; always Block.
func (r Rule) Action() Action { return Block }

// AnyApp reports whether the rule applies to every program.
func (r Rule) AnyApp() bool { return r.App == "" && r.Exe == "" }

// Capabilities describes what a backend can enforce.
type Capabilities struct {
	// PerApp is true when rules can target a single program.
	PerApp bool
	// PerDestination is true when rules can target addresses.
	PerDestination bool
	// NeedsAdmin is true when applying rules needs administrator rights.
	NeedsAdmin bool
	// Backend names the mechanism, such as "Windows Firewall".
	Backend string
	// Notes explains limits worth showing to the user.
	Notes string
}

// Status describes the firewall's current state.
type Status struct {
	// Enabled is true when the user has turned the firewall on.
	Enabled bool
	// Applied is the number of rules the backend enforced on the last apply.
	Applied int
	// Errors lists problems from the last apply, such as rules that couldn't
	// be enforced.
	Errors []string
	// Backend names the enforcement mechanism.
	Backend string
	// SystemFirewallOff is true when the operating system's firewall is off,
	// so MiddleMan's rules have no effect. MiddleMan never turns it on.
	SystemFirewallOff bool
}

// Backend enforces rules through the operating system.
type Backend interface {
	// Name names the mechanism, such as "nftables".
	Name() string
	// Capabilities describes what the backend can enforce.
	Capabilities() Capabilities
	// Apply makes the system match exactly this set of rules: it adds
	// missing rules and removes stale ones. The rules are enabled and
	// resolved: Dest is "" or a comma-separated list of IP addresses and
	// CIDR prefixes. Rules it can't enforce while it enforces the others are
	// reported with a *PartialError.
	Apply(rules []Rule) error
	// Clear removes everything this backend ever created, including rules
	// from earlier runs. It succeeds when there is nothing to remove.
	Clear() error
	// SystemFirewallOff reports whether the operating system's firewall is
	// off, so rules wouldn't take effect.
	SystemFirewallOff() bool
}

// Validator is implemented by backends with extra requirements for rules,
// such as needing a program's full path.
type Validator interface {
	// Validate returns an error explaining why the backend can't enforce r.
	Validate(r Rule) error
}

// Problem is a rule that couldn't be enforced.
type Problem struct {
	// RuleID is the rule's ID.
	RuleID string
	// Reason explains what went wrong.
	Reason string
}

// String formats the problem for display.
func (p Problem) String() string { return p.RuleID + ": " + p.Reason }

// PartialError reports rules that a backend skipped while it applied the
// rest. The system matches the other rules.
type PartialError struct {
	// Problems lists the skipped rules.
	Problems []Problem
}

// Error lists the skipped rules.
func (e *PartialError) Error() string {
	parts := make([]string, len(e.Problems))
	for i, p := range e.Problems {
		parts[i] = p.String()
	}
	return fmt.Sprintf("%d rule(s) couldn't be applied: %s", len(e.Problems), strings.Join(parts, "; "))
}

// partial returns a *PartialError for problems, or nil when there are none.
func partial(problems []Problem) error {
	if len(problems) == 0 {
		return nil
	}
	return &PartialError{Problems: problems}
}

var (
	// ErrUnsupported is returned by backends on platforms without firewall
	// support.
	ErrUnsupported = errors.New("the firewall isn't supported on this platform")
	// ErrBlocksEverything is returned for a rule with neither a program nor
	// a destination, which would cut the device off the network.
	ErrBlocksEverything = errors.New("a rule needs a program or a destination: blocking all traffic would cut this device off the network")
	// ErrProtected is returned for a destination that includes loopback,
	// DHCP or a configured DNS server, which MiddleMan never blocks.
	ErrProtected = errors.New("destination is protected")
	// ErrNotFound is returned for an unknown rule ID.
	ErrNotFound = errors.New("no such rule")
)
